// Fábrica de conteúdo (09/10/2026): 5 ideias de post/reel por semana a partir do uso real, anonimizado.
const d = $input.first().json || {};
const NL = String.fromCharCode(10);
const sistema = [
  'Você é o estrategista de conteúdo do Dyno, um assessor pessoal no WhatsApp com duas vozes: o Dyno (dinheiro: gastos por texto, áudio ou foto do comprovante, contas a pagar, assinaturas, resumo do mês) e a Dina (lembretes que insistem até a pessoa confirmar, tarefas, listas, agenda). Instagram: @dynoapp.ia. Beta fechado com vagas limitadas, 60 dias grátis; entrada em dynoapp.com.br/beta.',
  'Você recebe os números agregados da última semana e frases reais (anonimizadas) que os clientes mandaram. Crie conteúdo para Instagram/TikTok/Status que mostre o produto resolvendo problemas reais do dia a dia.',
  'Devolva APENAS um JSON: {"resumo_semana": "1 frase", "numeros_destaque": ["até 4 números prontos para usar em post, ex.: 112 gastos anotados sem abrir planilha"], "ideias": [{"formato": "reel|carrossel|post|stories", "titulo": "curto", "gancho": "primeira frase/3 primeiros segundos", "roteiro": ["passo ou cena 1", "..."], "legenda": "legenda pronta com no máximo 3 hashtags", "cta": "chamada final", "baseado_em": "qual dado ou frase inspirou"}]}',
  'Regras: exatamente 5 ideias, variando formatos (pelo menos 2 reels). Nunca use nomes, números de telefone ou valores que identifiquem alguém; as frases de clientes servem de inspiração e devem ser reescritas de forma genérica. Use os números agregados com honestidade (não aumente). Linguagem brasileira, leve, sem promessas financeiras e sem termos técnicos (IA, n8n, modelo). Mostre a conversa no WhatsApp como cena sempre que possível. Português do Brasil.'
].join(NL);
const usuario = 'Números da semana (' + d.de + ' a ' + d.ate + '):' + NL + JSON.stringify(Object.assign({}, d, { exemplos: undefined, elogios: undefined })) + NL + NL +
  'Frases reais de clientes (anonimizadas):' + NL + (d.exemplos || []).map(x => '- ' + x).join(NL) + NL + NL + 'Elogios:' + NL + (d.elogios || []).map(x => '- ' + x).join(NL);
const payload = { model: 'gpt-6-luna', response_format: { type: 'json_object' }, messages: [{ role: 'system', content: sistema }, { role: 'user', content: usuario }] };
return [{ json: { dados: d, payload } }];

const r = $input.first().json || {};
const base = $('Montar pedido à IA').first().json;
const NL = String.fromCharCode(10);
let j = {};
try { j = JSON.parse(String(r.choices[0].message.content || '{}')); } catch (e) { j = { resumo_semana: 'Não consegui interpretar a resposta da IA.', ideias: [] }; }
const ic = { reel: '🎬', carrossel: '🖼️', post: '📝', stories: '📱' };
const partes = ['🏭 *Fábrica de conteúdo · semana de ' + DateTime.now().setZone('America/Sao_Paulo').minus({ days: 7 }).toFormat('dd/LL') + '*', j.resumo_semana || ''];
if (Array.isArray(j.numeros_destaque) && j.numeros_destaque.length) partes.push('*Números para usar:*' + NL + j.numeros_destaque.slice(0, 4).map(x => '• ' + x).join(NL));
(Array.isArray(j.ideias) ? j.ideias : []).slice(0, 5).forEach((x, i) => {
  partes.push((ic[String(x.formato || '').toLowerCase()] || '💡') + ' *' + (i + 1) + '. ' + (x.titulo || 'Ideia') + '* (' + (x.formato || '') + ')' + NL +
    '*Gancho:* ' + (x.gancho || '') + NL +
    (Array.isArray(x.roteiro) && x.roteiro.length ? '*Roteiro:*' + NL + x.roteiro.slice(0, 6).map((c, k) => (k + 1) + ') ' + c).join(NL) + NL : '') +
    '*Legenda:* ' + (x.legenda || '') + NL + '*CTA:* ' + (x.cta || '') + (x.baseado_em ? NL + '_Baseado em: ' + x.baseado_em + '_' : ''));
});
partes.push('As ideias usam só números somados e frases reescritas, sem nomes. Revise antes de postar.');
let texto = partes.filter(Boolean).join(NL + NL);
if (texto.length > 7000) texto = texto.slice(0, 6980) + '…';
return [{ json: { gravar: { p: { de: base.dados.de, ate: base.dados.ate, dados: Object.assign({}, base.dados, { exemplos: undefined }), ideias: j, texto, modelo: r.model || 'gpt-6-luna' } },
  uso: { p: { autor: 'Sistema', origem: 'fabrica_conteudo', tarefa: 'conteudo', provedor: 'openai', modelo: r.model || 'gpt-6-luna', uso: r.usage || {} } } } }];
